uv +=  0.1*bubbles*gmask;
dist = MinDistB(uv);
bdist = mix(dist,GetDistB(uv),.2);
dist_c = clamp(GetDistB2 (center),.1,.4); //center distance
float struc = GetBlurX(uv,focus).r;
ret = struc* col_struc *vec3(1.0 - bdist, 1.0 , 1.0 )+ pow(sat(struc), 4.0 ) * vec3 ( 0.0 , 1.0 ,.2);
vec4 noise9 = tex3D(sampler_noisevol_hq,
((uv.xyy*q28
)*uTexSize.xyy*texsize_noisevol_hq.zww
).xyz*
vec3(2.1, 2.0 , 2.0 )*0.05 +
uTime*vec3( 1.0 ,2.1,0.1)*q31
);
