if(ret.y> q25*q11         && ret.y<= q22*q12        )ret.x -= (noise9).y*.5;
if(ret.z> q24*q12         && ret.z<= q21*q13        )ret.y -= (noise9).z*.5;
//distant light
ret += gmask*bubbles.z * (1.0 + slow_roam_cos);
ret = mix(ret, vec3(.2,0.4,0.4) * 4.0*q19, sat(pow(bdist,1.5)));
float moon = (.5/length(sin(3.0 * (uv5))));
ret += sat(MinDistB(uv) * 6.0-5)*moon*vec3(1.6,1.6,1.6);
//Lamp
uv3 = uv-center;
float ddd = GetPixel(uv).r - GetPixel((uv-.5)*(1.01)+.5).r;
lamp = clamp01(1-4*length(uv3)) * (0.11+struc+ddd);
